const text = ($input.first().json.message?.text || '').toLowerCase().trim();

const rescheduleKw = [
  'reschedule','rebook','move appointment','change appointment',
  'postpone','cancel','cancellation'
];
const bookingKw = [
  'book','appointment','schedule','reserve','visit'
];
const reviewKw = [
  'thank','thanks','great','good','bad','terrible','awful','excellent',
  'poor','horrible','amazing','wonderful','worst','best','experience',
  'complaint','complain','satisfied','dissatisfied','happy','unhappy','rude'
];

function matches(kws) { return kws.some(k => text.includes(k)); }

let intent;
if (matches(rescheduleKw)) {
  intent = 'RESCHEDULE';
} else if (matches(bookingKw)) {
  intent = 'BOOKING_STEP';
} else if (matches(reviewKw)) {
  intent = 'REVIEW';
} else 
{
  intent = 'BOOKING_STEP'
}

return [{ json: {
  output: intent,
  original_text: $input.first().json.message?.text,
  chat_id: $input.first().json.message?.chat?.id
} }];

const raw = $input.first().json.output || '';

// Extract JSON block from agent output
const match = raw.match(/\{[\s\S]*?\}/);

let sentiment = 'neutral';
let category = 'other';
let summary = '';
let rating = 3;

if (match) {
  try {
    const parsed = JSON.parse(match[0]);
    sentiment = (parsed.sentiment || 'neutral').toLowerCase().trim();
    category = (parsed.category || 'other').toLowerCase().trim();
    summary = parsed.summary || '';
    if (parsed.rating !== undefined && !isNaN(Number(parsed.rating))) {
      rating = Math.min(5, Math.max(1, Number(parsed.rating)));
    } else {
      if (sentiment === 'positive') rating = 5;
      else if (sentiment === 'negative') rating = 1;
      else rating = 3;
    }
  } catch(e) {}
}

// Fallback: keyword scan if JSON parse failed
if (!summary) {
  const lower = raw.toLowerCase();
  if (lower.includes('negative') || lower.includes('complaint') || lower.includes('bad')) {
    sentiment = 'negative';
    rating = 1;
  } else if (lower.includes('positive') || lower.includes('great') || lower.includes('good')) {
    sentiment = 'positive';
    rating = 5;
  }
}

return [{ json: {
  sentiment,
  category,
  summary,
  rating,
  chat_id: $('Telegram Trigger').first().json.message.chat.id,
  original_text: $('Telegram Trigger').first().json.message.text
}}];
